     */
    fun `candidateMenuRun`(`index`: kotlin.UInt, `action`: kotlin.String): kotlin.Boolean
    
    /**
     * 第 `index`（全量绝对下标）个候选的提示（编码 / 读音 / 释义…），与电脑版候选悬停气泡
