            return FfiConverterULong.lift(
    callWithHandle {
    uniffiRustCallWithError(ConfigException) { _status ->
    UniffiLib.uniffi_wind_android_fn_method_windcore_assoc_history_clear(
        it,
        _status)
}
    }
    )
    }
    

    
